import {tropical} from './art.mjs';
// Existing isolated Superwin cabinet artwork; no recorder text, controls, balances or captured game page.
const sources={"hot-title.webp":"data:image/webp;base64,","foxy-title.webp":"data:image/webp;base64,","forest-middle.webp":"data:image/webp;base64,","forest-left.webp":"data:image/webp;base64,","forest-right.webp":"data:image/webp;base64,","forest-top-right.webp":"data:image/webp;base64,","forest-bottom.webp":"data:image/webp;base64,"};
const load=name=>new Promise(resolve=>{const image=new Image();image.onload=()=>resolve(image);image.onerror=()=>resolve(null);image.src=sources[name];});
function titleMask(image,foxy){
 const out=document.createElement('canvas');out.width=image.width;out.height=image.height;const c=out.getContext('2d');c.drawImage(image,0,0);const data=c.getImageData(0,0,out.width,out.height),p=data.data;
 for(let y=0;y<out.height;y++)for(let x=0;x<out.width;x++){const i=(y*out.width+x)*4,r=p[i],g=p[i+1],b=p[i+2];const foreground=Math.max(r,b),alpha=Math.max(0,Math.min(1,(foreground-42)/40));p[i+3]=Math.round(p[i+3]*alpha);if(foxy&&x>out.width*.88&&y>out.height*.9)p[i+3]=0;}
 c.putImageData(data,0,0);return out;
}
function forestMask(image,feather){
 const out=document.createElement('canvas');out.width=image.width;out.height=image.height;const c=out.getContext('2d');c.drawImage(image,0,0);const data=c.getImageData(0,0,out.width,out.height),p=data.data;
 for(let y=0;y<out.height;y++)for(let x=0;x<out.width;x++){const i=(y*out.width+x)*4;const light=Math.max(p[i],p[i+1],p[i+2]);let fade=1;if(feather==='left')fade=Math.min(1,(out.width-x)/(out.width*.22),y/(out.height*.1),(out.height-y)/(out.height*.1));if(feather==='right')fade=Math.min(1,x/(out.width*.22),y/(out.height*.1),(out.height-y)/(out.height*.1));if(feather==='vertical')fade=Math.min(1,y/(out.height*.12),(out.height-y)/(out.height*.12));if(feather==='top')fade=Math.min(1,x/(out.width*.07),(out.height-y)/(out.height*.15));p[i+3]=Math.round(p[i+3]*Math.max(0,Math.min(1,(light-48)/25))*Math.max(0,fade));}
 c.putImageData(data,0,0);return out;
}
export async function cabinetArtwork(g){
 if(typeof Image==='undefined')return null;const foxy=g.id==='hot_foxy_20',title=await load(foxy?'foxy-title.webp':'hot-title.webp');if(!title)return null;
 const result={title:titleMask(title,foxy),layers:[]};if(foxy){
  const placements=[['forest-top-right.webp','top',220,0,187,73],['forest-middle.webp','vertical',13,392,394,99],['forest-left.webp','left',13,480,65,150],['forest-right.webp','right',342,480,65,150],['forest-bottom.webp','vertical',13,630,394,28]];
  result.layers=await Promise.all(placements.map(async([name,feather,...box])=>{const image=await load(name);return image?{image:forestMask(image,feather),box}:null;}));
 for(const layer of result.layers.filter(Boolean)){if(layer.box[1]!==480)continue;const right=layer.box[0]>200,source=layer.image,out=document.createElement('canvas');out.width=source.width;out.height=right?160:205;const c=out.getContext('2d');c.drawImage(source,0,right?100:120,source.width,out.height,0,0,out.width,out.height);c.globalCompositeOperation='destination-in';const f=c.createLinearGradient(0,0,0,out.height);f.addColorStop(0,'#0000');f.addColorStop(.12,'#000');f.addColorStop(.88,'#000');f.addColorStop(1,'#0000');c.fillStyle=f;c.fillRect(0,0,out.width,out.height);result.layers.push({image:out,box:[right?342:13,735,65,165]});}
 }return result;
}
export function drawCabinetArtwork(c,art,g){
 if(!art)return;c.save();if(g.id==='hot_foxy_20'){c.fillStyle='#000';c.fillRect(0,0,420,900);c.beginPath();c.rect(13,0,394,900);c.clip();const f=c.createRadialGradient(210,410,80,210,430,640);f.addColorStop(0,'#00352a');f.addColorStop(.6,'#00291f');f.addColorStop(1,'#001b16');c.fillStyle=f;c.fillRect(0,0,420,900);c.save();c.globalAlpha=.13;tropical(c,135,690,1.7,.3,'#1f5d48');tropical(c,300,728,1.4,-.9,'#1d5e48');tropical(c,185,805,1.3,2.5,'#235b45');c.restore();}for(const layer of art.layers||[])if(layer)c.drawImage(layer.image,...layer.box);c.restore();
}
export function drawCabinetTitle(c,art,g){if(!art?.title)return false;const foxy=g.id==='hot_foxy_20';c.drawImage(art.title,...(foxy?[39,3,151,63]:[79,77,270,40]));return true;}
